         function synthKH(nx, nz, billowAmp){
          var b = [], u = [], w = [];
          for(var k = 0; k < nz; k++){
           var z = - 5.0 + 10.0 * (k + 0.5) / nz;
           for(var i = 0; i < nx; i++){
            var
             x = - 5.0 + 10.0 * (i + 0.5) / nx,
             kx = 4.0 * Math.PI * x / 10.0,
             env = Math.exp(- 0.5 * (z / 0.85) * (z / 0.85)),
             disp = billowAmp * env * Math.sin(kx - 0.55 * z),
             zb = z - 1.35 * disp;
            b.push(0.025 * Math.tanh(zb / 0.32));
            u.push(Math.tanh(zb) - 0.45 * billowAmp * env * Math.cos(kx));
            w.push(0.55 * billowAmp * env * Math.cos(kx));
           }
          }
          return {b: b, u: u, w: w};
         }
